// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint256 value, address target, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(target != address(c));
        vm.assume(value <= address(this).balance);
        vm.deal(actor, value);
        vm.prank(actor);
        bool callOk;
        try c.sendMoney(target, value, data) { callOk = true; } catch { callOk = false; }
        assertTrue(!callOk);
    }
}
